13	@Repository
14	public class AllocationRepository {
15	
16	    /** 分配行（含盲底，仅供服务层内部使用）。 */
17	    public record AllocationRow(
18	            long id,
19	            String experimentId,
20	            String participantId,
21	            int blockNo,
22	            int seatNo,
23	            String blindCode,
24	            String status,
25	            String assignedActor,
26	            long assignedAt,
27	            Long withdrawnAt) {
28	    }
29	
30	    private static final RowMapper<AllocationRow> ALLOCATION_MAPPER = (rs, n) -> new AllocationRow(
31	            rs.getLong("id"),
32	            rs.getString("experiment_id"),
33	            rs.getString("participant_id"),
34	            rs.getInt("block_no"),
35	            rs.getInt("seat_no"),
36	            rs.getString("blind_code"),
37	            rs.getString("status"),
38	            rs.getString("assigned_actor"),
39	            rs.getLong("assigned_at"),
40	            (Long) rs.getObject("withdrawn_at"));
41	
42	    private final JdbcTemplate jdbc;
43	
44	    public AllocationRepository(JdbcTemplate jdbc) {
45	        this.jdbc = jdbc;
46	    }
47	
48	    public void insert(AllocationRow row) {
49	        jdbc.update("INSERT INTO allocation ("
50	                        + "experiment_id, participant_id, block_no, seat_no, blind_code, "
51	                        + "status, assigned_actor, assigned_at, withdrawn_at"
52	                        + ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
53	                row.experimentId(), row.participantId(), row.blockNo(), row.seatNo(), row.blindCode(),
54	                row.status(), row.assignedActor(), row.assignedAt(), row.withdrawnAt());
55	    }
56	
57	    public AllocationRow findByExperimentAndParticipant(String experimentId, String participantId) {
58	        List<AllocationRow> rows = jdbc.query(
59	                "SELECT id, experiment_id, participant_id, block_no, seat_no, blind_code, status, "
60	                        + "assigned_actor, assigned_at, withdrawn_at "
61	                        + "FROM allocation WHERE experiment_id = ? AND participant_id = ?",
62	                ALLOCATION_MAPPER, experimentId, participantId);
63	        return rows.isEmpty() ? null : rows.get(0);
64	    }
65	
66	    /**
67	     * 原子领取按区组、席位顺序排列的第一个空位：把尚未被占用的最小 block_no/seat_no
68	     * 关联给新参与者。依赖 allocation(experiment_id, block_no, seat_no) 唯一索引兜底并发。
69	     *
70	     * @return 领取到的席位；实验满额时返回 null
71	     */
72	    public VacantSeat takeFirstVacantSeat(String experimentId) {
73	        List<VacantSeat> seats = jdbc.query(
74	                "SELECT s.block_no, s.seat_no FROM seat s "
75	                        + "LEFT JOIN allocation a "
76	                        + "ON a.experiment_id = s.experiment_id "
77	                        + "AND a.block_no = s.block_no "
78	                        + "AND a.seat_no = s.seat_no "
79	                        + "WHERE s.experiment_id = ? AND a.id IS NULL "
80	                        + "ORDER BY s.block_no, s.seat_no LIMIT 1",
81	                (rs, n) -> new VacantSeat(rs.getInt(1), rs.getInt(2)),
82	                experimentId);
83	        return seats.isEmpty() ? null : seats.get(0);
84	    }
85	
86	    /** 原子领取结果。 */
87	    public record VacantSeat(int blockNo, int seatNo) {
88	    }
89	
90	    public long countOccupied(String experimentId) {
91	        Long count = jdbc.queryForObject(
92	                "SELECT COUNT(*) FROM allocation WHERE experiment_id = ?", Long.class, experimentId);
93	        return count == null ? 0 : count;
94	    }
95	
96	    /**
97	     * 退组：仅 ASSIGNED -> WITHDRAWN，不释放席位。
98	     *
99	     * @return 受影响行数；0 表示不存在或已退组
100	     */
101	    public int markWithdrawn(long allocationId, long withdrawnAt) {
102	        return jdbc.update(
103	                "UPDATE allocation SET status = 'WITHDRAWN', withdrawn_at = ? "
104	                        + "WHERE id = ? AND status = 'ASSIGNED'",
105	                withdrawnAt, allocationId);
106	    }
107	
108	    /**
109	     * 插入时若参与者已在同实验占席，抛出由唯一约束触发的 DuplicateKeyException。
110	     */
111	    public boolean isDuplicateParticipant(DuplicateKeyException e) {
112	        return e.getMessage() != null && e.getMessage().contains("uq_allocation_participant");
113	    }
114	
115	    public boolean isDuplicateSeat(DuplicateKeyException e) {
116	        return e.getMessage() != null && e.getMessage().contains("uq_allocation_seat");
117	    }
118	
119	    public boolean isDuplicateBlindCode(DuplicateKeyException e) {
120	        return e.getMessage() != null && e.getMessage().contains("uq_allocation_blind_code");
121	    }
