 * @param role    角色（COORDINATOR / REVIEWER）
 */
public record Actor(String actorId, Role role) {

    public boolean isCoordinator() {
        return role == Role.COORDINATOR;
    }

    public boolean isReviewer() {
        return role == Role.REVIEWER;
    }
}

