1	package com.example.starter.blind.web;
2	
3	import com.example.starter.blind.ApiException;
4	import com.example.starter.blind.dto.ErrorBody;
5	import com.example.starter.blind.service.IdempotencyService;
6	import org.springframework.http.HttpStatus;
7	import org.springframework.http.ResponseEntity;
8	import org.springframework.http.converter.HttpMessageNotReadableException;
9	import org.springframework.validation.FieldError;
10	import org.springframework.web.bind.MethodArgumentNotValidException;
11	import org.springframework.web.bind.MissingRequestHeaderException;
12	import org.springframework.web.bind.annotation.ExceptionHandler;
13	import org.springframework.web.bind.annotation.RestControllerAdvice;
14	
15	/**
16	 * 全局异常处理；错误信息不包含处理代码或席位序号。
17	 */
18	@RestControllerAdvice
19	public class GlobalExceptionHandler {
20	
21	    @ExceptionHandler(ApiException.class)
22	    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
23	        return ResponseEntity.status(ex.getStatus())
24	                .body(new ErrorBody(ex.getStatus().getReasonPhrase(), ex.getMessage()));
25	    }
26	
27	    @ExceptionHandler(MethodArgumentNotValidException.class)
28	    public ResponseEntity<ErrorBody> handleValidation(MethodArgumentNotValidException ex) {
29	        FieldError fieldError = ex.getBindingResult().getFieldError();
30	        String message = fieldError != null ? fieldError.getDefaultMessage() : "请求参数不合法";
31	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
32	                .body(new ErrorBody(HttpStatus.BAD_REQUEST.getReasonPhrase(), message));
33	    }
34	
35	    @ExceptionHandler(HttpMessageNotReadableException.class)
36	    public ResponseEntity<ErrorBody> handleUnreadable(HttpMessageNotReadableException ex) {
37	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
38	                .body(new ErrorBody(HttpStatus.BAD_REQUEST.getReasonPhrase(), "请求体格式不正确"));
39	    }
40	
41	    @ExceptionHandler(MissingRequestHeaderException.class)
42	    public ResponseEntity<ErrorBody> handleMissingHeader(MissingRequestHeaderException ex) {
43	        String message = IdempotencyService.HEADER_REQUEST_ID.equals(ex.getHeaderName())
44	                ? "写操作必须携带全局唯一 X-Request-Id 请求头"
45	                : "缺少必需请求头: " + ex.getHeaderName();
46	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
47	                .body(new ErrorBody(HttpStatus.BAD_REQUEST.getReasonPhrase(), message));
48	    }
49	}
