1	package com.example.starter.blind;
2	
3	import com.fasterxml.jackson.databind.JsonNode;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import org.junit.jupiter.api.Test;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.boot.test.context.SpringBootTest;
8	import org.springframework.boot.test.web.client.TestRestTemplate;
9	import org.springframework.http.HttpEntity;
10	import org.springframework.http.HttpHeaders;
11	import org.springframework.http.HttpMethod;
12	import org.springframework.http.MediaType;
13	import org.springframework.http.ResponseEntity;
14	
15	import java.util.ArrayList;
16	import java.util.HashSet;
17	import java.util.List;
18	import java.util.Set;
19	
20	import static org.junit.jupiter.api.Assertions.assertEquals;
21	import static org.junit.jupiter.api.Assertions.assertFalse;
22	import static org.junit.jupiter.api.Assertions.assertNotNull;
23	import static org.junit.jupiter.api.Assertions.assertTrue;
24	
25	/**
26	 * 主流程：建实验、顺序分配、盲码视图、满额、退组不释放席位、关闭拒绝新增。
27	 */
28	@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
29	class BlindExperimentApiTest extends AbstractBlindIntegrationTest {
30	
31	    @Autowired
32	    private TestRestTemplate rest;
33	
34	    private final ObjectMapper mapper = new ObjectMapper();
35	
36	    private HttpHeaders headers(String actor, String role, String requestId) {
37	        HttpHeaders h = new HttpHeaders();
38	        h.set("X-Actor-Id", actor);
39	        h.set("X-Role", role);
40	        if (requestId != null) {
41	            h.set("X-Request-Id", requestId);
42	        }
43	        h.setContentType(MediaType.APPLICATION_JSON);
44	        return h;
45	    }
46	
47	    private ResponseEntity<String> exchange(String path, HttpMethod method,
48	                                            HttpHeaders headers, String body) {
49	        return rest.exchange(path, method, new HttpEntity<>(body, headers), String.class);
50	    }
51	
52	    private JsonNode json(ResponseEntity<String> response) throws Exception {
53	        return mapper.readTree(response.getBody());
54	    }
55	
56	    @Test
57	    void createExperiment_fixedBlocksAndSeats_twoATwoBPerBlock() {
58	        ResponseEntity<String> resp = exchange("/api/experiments/EXP-1", HttpMethod.POST,
59	                headers("c1", "COORDINATOR", "req-create-1"), "{\"blockCount\":2}");
60	        assertEquals(201, resp.getStatusCode().value());
61	        JsonNode body = resp.getBody() == null ? null : parse(resp.getBody());
62	        assertNotNull(body);
63	        assertEquals("EXP-1", body.path("experimentId").asText());
64	        assertEquals(2, body.path("blockCount").asInt());
65	        assertEquals(4, body.path("seatsPerBlock").asInt());
66	        assertEquals(8, body.path("totalSeats").asInt());
67	        assertEquals("OPEN", body.path("status").asText());
68	        assertEquals(1_700_000_000_000L, body.path("createdAt").asLong());
69	        // 普通视图不得含盲底字段
70	        assertFalse(body.has("treatment"));
71	        assertFalse(body.has("seatNo"));
72	
73	        // 库内席位映射：每区组按顺序两个 A、两个 B
74	        List<String> treatments = jdbc.queryForList(
75	                "SELECT treatment FROM seat WHERE experiment_id = 'EXP-1' "
76	                        + "ORDER BY block_no, seat_no", String.class);
77	        assertEquals(List.of("A", "A", "B", "B", "A", "A", "B", "B"), treatments);
78	        assertEquals(8, jdbc.queryForObject(
79	                "SELECT COUNT(*) FROM seat WHERE experiment_id = 'EXP-1'", Integer.class));
80	    }
81	
82	    @Test
83	    void register_assignsInBlockAndSeatOrder_returnsBlindViewOnly() throws Exception {
84	        createExperiment("EXP-2", 2, "req-create-2");
85	
86	        List<JsonNode> allocations = new ArrayList<>();
87	        Set<String> codes = new HashSet<>();
88	        int[] expectedBlocks = {1, 1, 1, 1, 2, 2, 2, 2};
89	        for (int i = 1; i <= 8; i++) {
90	            ResponseEntity<String> resp = exchange(
91	                    "/api/experiments/EXP-2/participants/P" + i + "/allocations",
92	                    HttpMethod.POST,
93	                    headers("c1", "COORDINATOR", "req-alloc-" + i), null);
94	            assertEquals(201, resp.getStatusCode().value(), "参与者 P" + i + " 应分配成功");
95	            JsonNode node = json(resp);
96	            assertEquals("P" + i, node.path("participantId").asText());
97	            assertEquals(expectedBlocks[i - 1], node.path("blockNo").asInt());
98	            assertEquals("ASSIGNED", node.path("status").asText());
99	            String blindCode = node.path("blindCode").asText();
100	            assertTrue(blindCode.matches("[A-Z2-9]{12}"), "盲码应为12位无含义随机码: " + blindCode);
101	            assertTrue(codes.add(blindCode), "盲码必须全局唯一");
102	            // 普通登记响应不得包含处理代码或席位序号
103	            assertFalse(node.has("treatment"), "响应不得包含处理代码");
104	            assertFalse(node.has("seatNo"), "响应不得包含席位序号");
105	            allocations.add(node);
106	        }
107	
108	        // 第九个参与者：满额 422
109	        ResponseEntity<String> full = exchange(
110	                "/api/experiments/EXP-2/participants/P9/allocations", HttpMethod.POST,
111	                headers("c1", "COORDINATOR", "req-alloc-9"), null);
112	        assertEquals(422, full.getStatusCode().value());
113	
114	        // REVIEWER 普通查询同样只见盲码视图
115	        ResponseEntity<String> query = exchange(
116	                "/api/experiments/EXP-2/participants/P1", HttpMethod.GET,
117	                headers("r1", "REVIEWER", null), null);
118	        assertEquals(200, query.getStatusCode().value());
119	        JsonNode queried = json(query);
120	        assertEquals(allocations.get(0).path("blindCode").asText(),
121	                queried.path("blindCode").asText());
122	        assertEquals(1, queried.path("blockNo").asInt());
123	        assertFalse(queried.has("treatment"));
124	        assertFalse(queried.has("seatNo"));
125	    }
126	
127	    @Test
128	    void withdraw_keepsSeatAndShowsStatus_rejectsNewAndDuplicate() throws Exception {
129	        createExperiment("EXP-3", 2, "req-create-3");
130	        for (int i = 1; i <= 8; i++) {
131	            assertEquals(201, exchange(
132	                    "/api/experiments/EXP-3/participants/P" + i + "/allocations",
133	                    HttpMethod.POST, headers("c1", "COORDINATOR", "req-w-alloc-" + i), null)
134	                    .getStatusCode().value());
135	        }
136	
137	        clock.advance(5_000L);
138	        ResponseEntity<String> withdrawn = exchange(
139	                "/api/experiments/EXP-3/participants/P1/withdrawal", HttpMethod.POST,
140	                headers("c1", "COORDINATOR", "req-withdraw-1"), null);
141	        assertEquals(200, withdrawn.getStatusCode().value());
142	        JsonNode node = json(withdrawn);
143	        assertEquals("WITHDRAWN", node.path("status").asText());
144	        assertEquals(1_700_000_005_000L, node.path("withdrawnAt").asLong());
145	        assertFalse(node.has("treatment"));
146	        assertFalse(node.has("seatNo"));
147	
148	        // 普通查询返回退组状态
149	        ResponseEntity<String> query = exchange(
150	                "/api/experiments/EXP-3/participants/P1", HttpMethod.GET,
151	                headers("c1", "COORDINATOR", null), null);
152	        assertEquals("WITHDRAWN", json(query).path("status").asText());
153	
154	        // 席位不释放：新参与者仍被拒（满额）
155	        ResponseEntity<String> newOne = exchange(
156	                "/api/experiments/EXP-3/participants/P9/allocations", HttpMethod.POST,
157	                headers("c1", "COORDINATOR", "req-w-alloc-9"), null);
158	        assertEquals(422, newOne.getStatusCode().value());
159	
160	        // 同参与者不占第二席（已退组也不可重新登记）
161	        ResponseEntity<String> duplicate = exchange(
162	                "/api/experiments/EXP-3/participants/P1/allocations", HttpMethod.POST,
163	                headers("c1", "COORDINATOR", "req-w-alloc-p1-again"), null);
164	        assertEquals(409, duplicate.getStatusCode().value());
165	
166	        // 重复退组 409
167	        ResponseEntity<String> twice = exchange(
168	                "/api/experiments/EXP-3/participants/P1/withdrawal", HttpMethod.POST,
169	                headers("c1", "COORDINATOR", "req-withdraw-1-again"), null);
170	        assertEquals(409, twice.getStatusCode().value());
171	
172	        // 席位仍保留 8 条分配
173	        assertEquals(8, jdbc.queryForObject(
174	                "SELECT COUNT(*) FROM allocation WHERE experiment_id = 'EXP-3'", Integer.class));
175	    }
176	
177	    @Test
178	    void close_rejectsNewAllocations_andDoubleCloseConflicts() throws Exception {
179	        createExperiment("EXP-4", 2, "req-create-4");
180	        ResponseEntity<String> closed = exchange("/api/experiments/EXP-4/close",
181	                HttpMethod.POST, headers("c1", "COORDINATOR", "req-close-4"), null);
182	        assertEquals(200, closed.getStatusCode().value());
183	        assertEquals("CLOSED", json(closed).path("status").asText());
184	
185	        ResponseEntity<String> allocate = exchange(
186	                "/api/experiments/EXP-4/participants/P1/allocations", HttpMethod.POST,
187	                headers("c1", "COORDINATOR", "req-closed-alloc"), null);
188	        assertEquals(409, allocate.getStatusCode().value());
189	
190	        ResponseEntity<String> again = exchange("/api/experiments/EXP-4/close",
191	                HttpMethod.POST, headers("c1", "COORDINATOR", "req-close-4-again"), null);
192	        assertEquals(409, again.getStatusCode().value());
193	
194	        assertEquals("CLOSED", jdbc.queryForObject(
195	                "SELECT status FROM experiment WHERE id = 'EXP-4'", String.class));
196	
197	        // 查询实验信息
198	        ResponseEntity<String> view = exchange("/api/experiments/EXP-4", HttpMethod.GET,
199	                headers("r1", "REVIEWER", null), null);
200	        assertEquals(200, view.getStatusCode().value());
201	        assertEquals("CLOSED", json(view).path("status").asText());
202	    }
203	
204	    @Test
205	    void createExperiment_maxEightBlocks_has32Seats() {
206	        ResponseEntity<String> resp = exchange("/api/experiments/EXP-MAX", HttpMethod.POST,
207	                headers("c1", "COORDINATOR", "req-create-max"), "{\"blockCount\":8}");
208	        assertEquals(201, resp.getStatusCode().value());
209	        JsonNode body = parse(resp.getBody());
210	        assertEquals(8, body.path("blockCount").asInt());
211	        assertEquals(32, body.path("totalSeats").asInt());
212	        assertEquals(32, jdbc.queryForObject(
213	                "SELECT COUNT(*) FROM seat WHERE experiment_id = 'EXP-MAX'", Integer.class));
214	        // 每区组仍是两个 A 两个 B
215	        assertEquals(16L, jdbc.queryForObject(
216	                "SELECT COUNT(*) FROM seat WHERE experiment_id = 'EXP-MAX' AND treatment = 'A'",
217	                Long.class));
218	        assertEquals(16L, jdbc.queryForObject(
219	                "SELECT COUNT(*) FROM seat WHERE experiment_id = 'EXP-MAX' AND treatment = 'B'",
220	                Long.class));
221	    }
222	
223	    @Test
224	    void invalidBlockCountAndMissingResources_fail() {
225	        ResponseEntity<String> tooFew = exchange("/api/experiments/EXP-X", HttpMethod.POST,
226	                headers("c1", "COORDINATOR", "req-bad-1"), "{\"blockCount\":1}");
227	        assertEquals(400, tooFew.getStatusCode().value());
228	        ResponseEntity<String> tooMany = exchange("/api/experiments/EXP-Y", HttpMethod.POST,
229	                headers("c1", "COORDINATOR", "req-bad-2"), "{\"blockCount\":9}");
230	        assertEquals(400, tooMany.getStatusCode().value());
231	        ResponseEntity<String> missingBody = exchange("/api/experiments/EXP-Z", HttpMethod.POST,
232	                headers("c1", "COORDINATOR", "req-bad-3"), null);
233	        assertEquals(400, missingBody.getStatusCode().value());
234	
235	        assertEquals(404, exchange("/api/experiments/NOPE", HttpMethod.GET,
236	                headers("c1", "COORDINATOR", null), null).getStatusCode().value());
237	        assertEquals(404, exchange(
238	                "/api/experiments/EXP-X/participants/P1/allocations", HttpMethod.POST,
239	                headers("c1", "COORDINATOR", "req-bad-4"), null).getStatusCode().value());
240	    }
241	
242	    private void createExperiment(String id, int blockCount, String requestId) {
243	        ResponseEntity<String> resp = exchange("/api/experiments/" + id, HttpMethod.POST,
244	                headers("c1", "COORDINATOR", requestId),
245	                "{\"blockCount\":" + blockCount + "}");
246	        assertEquals(201, resp.getStatusCode().value());
247	    }
248	
249	    private JsonNode parse(String body) {
250	        try {
251	            return mapper.readTree(body);
252	        } catch (Exception e) {
253	            throw new RuntimeException(e);
254	        }
255	    }
256	}
