@Transactional
public ResultView submit(String experimentId, String participantId, int value, String actorId) {
    ExperimentRow experiment = experimentRepository.lockById(experimentId);
    if (experiment == null) throw notFound;
    if (!"OPEN".equals(experiment.status())) throw conflict("实验已关闭，拒绝提交或修订结果");
    AllocationRow allocation = allocationRepository.findByExperimentAndParticipant(...);
    if (allocation == null) throw notFound("参与者尚未在该实验登记");
    if ("WITHDRAWN".equals(allocation.status())) throw conflict("参与者已退组，拒绝提交或修订结果");
    ResultRow latest = resultRepository.findLatest(...);
    int version = latest == null ? 1 : latest.version() + 1;
    long now = clock.nowMillis();
    resultRepository.insert(new ResultRow(..., version, value, actorId, now));
    return new ResultView(...);
}
