/**
 * 枚举 values 中选出 countA 个作为“A组”的全部组合；
 * 返回 {k, n}：统计量分子大于等于观察分子的组合数 k 与总组合数 n。
 */
private long[] enumerate(long[] values, int countA, int countB, long totalSum,
                         long observedNum) {
    long[] counts = new long[2];
    combine(values, 0, countA, 0L, countB, totalSum, observedNum, counts);
    return counts;
}

private void combine(long[] values, int index, int remaining, long chosenSum,
                     int countB, long totalSum, long observedNum, long[] counts) {
    if (remaining == 0) {
        counts[1]++;
        long num = Math.abs(chosenSum * countB - (totalSum - chosenSum) * countA(counts));
        // countA 通过 values 与 remaining 无法回推，改用外层传入；见下方重载。
        counts[0] += num >= observedNum ? 1 : 0;
        return;
    }
    for (int i = index; i <= values.length - remaining; i++) {
        combine(values, i + 1, remaining - 1, chosenSum + values[i],
                countB, totalSum, observedNum, counts);
    }
}

private int countA(long[] counts) {
    // 占位：实际 countA 由调用方传入，见 analyze 中的调用方式。
    throw new UnsupportedOperationException();
}

